// AI: below section was generated by an AI
export function createFleetMigrationState() {
	return {updated:new Set(),skipped:new Set(),failed:new Set(),complete:false};
}

function macFrom(line){return line.match(/\bmac=([0-9a-f]{12})\b/i)?.[1].toLowerCase();}

// Records only evidence emitted by the established laptop batch updater.
export function consumeBatchLine(state,line) {
	const mac=macFrom(line);
	if (/^BATCH_UPGRADE_OK\b/.test(line) && mac) state.updated.add(mac);
	else if (/^SKIPPED\b/.test(line) && mac) state.skipped.add(mac);
	else if (/^FAILED\b/.test(line) && mac) state.failed.add(mac);
	if (/^BATCH_COMPLETE\b/.test(line)) state.complete=true;
	return state;
}

export function summarizeFleetMigration(state) {
	return {
		schemaVersion:1,
		adapter:"easy-flash-local-laptop",
		transport:"legacy-broadcast",
		complete:state.complete,
		counts:{updated:state.updated.size,skipped:state.skipped.size,failed:state.failed.size},
		devices:{updated:[...state.updated],skipped:[...state.skipped],failed:[...state.failed]},
		absentFleetStatus:"unknown",
		fleetCurrent:false,
	};
}

export function validateMigrationAuthority({lock,checkout,artifact,contractArtifact}) {
	if (!/^https:\/\/github\.com\/SteveEisner\/WLEDtubes(?:\.git)?$/.test(lock?.repository || "")) throw new Error("Pinned WLEDTubes repository is invalid");
	if (!/^[a-f0-9]{40}$/.test(lock?.commit || "") || checkout?.commit !== lock.commit) throw new Error("WLEDTubes checkout is not at the pinned commit");
	if (checkout.remote?.replace(/\.git$/,"") !== lock.repository.replace(/\.git$/,"")) throw new Error("WLEDTubes checkout remote is not the pinned repository");
	if (checkout.clean !== true) throw new Error("WLEDTubes checkout must be clean");
	if (!Number.isSafeInteger(artifact?.sizeBytes) || artifact.sizeBytes <= 0 || !/^[a-f0-9]{64}$/.test(artifact.sha256 || "")) throw new Error("OTA artifact identity is invalid");
	if (artifact.sizeBytes !== contractArtifact?.lengthBytes || artifact.sha256 !== contractArtifact?.sha256) throw new Error("OTA artifact does not match the frozen contract");
}
